def parse_ie(data):
    if len(data) < 2:
        raise ValueError('missing IE type')
    ie_type = int.from_bytes(data[0:2], 'big')
    length = int.from_bytes(data[2:4], 'big')
    value = data[4:4 + length]
    if len(value) != length:
        raise ValueError('truncated IE value')
    return ie_type, value
